/** Construction options for {@link BinaryCommandExecutor}. */
interface BinaryCommandExecutorOptions {
    /** Layout root; the binary is `<objectiveaiDir>/bin/objectiveai[.exe]`. */
    objectiveaiDir?: string;
    /** Extra environment variables layered onto the child's env. */
    extraEnv?: Record<string, string>;
    /** Kill the child when the stream is dropped (default false). */
    killOnDrop?: boolean;
    /** Detach the child so it outlives the parent (default false). */
    detach?: boolean;
}
declare class BinaryCommandExecutor {
    private readonly options;
    constructor(options?: BinaryCommandExecutorOptions);
    execute(request: CliCommandRequest): AsyncGenerator<unknown>;
    private resolveBinary;
}

declare class PluginCommandExecutor {
    private static _instance;
    private counter;
    private readonly pending;
    private alive;
    private writeChain;
    private listenerReady;
    /** The process-wide singleton (captures the global stdin/stdout). */
    static instance(): PluginCommandExecutor;
    /**
     * Send `request` to the host and stream back its responses (yielded raw;
     * the caller's `CliStream` discriminates errors vs responses). Safe to call
     * concurrently from any number of parallel callers.
     */
    execute(request: CliCommandRequest): AsyncIterable<unknown>;
    /** Serialize every write to stdout behind the listener being ready. */
    private write;
    /** Start the single stdin reader once. */
    private ensureListener;
    /** Route one inbound NDJSON line to the matching id's channel. */
    private onLine;
}

/**
 * Viewer executor: runs a typed cli request on the host viewer and streams
 * the host's `cli_command` events back. Takes no construction options.
 *
 * `request` is the serde JSON of the Rust SDK's `cli::command::Request`; the
 * iframe posts it to the host bridge, which hands the JSON to the objectiveai
 * cli via its top-level `--request` flag and forwards each JSONL output line
 * (`{"type":"error",…}` envelopes or response lines) as a `cli_command`
 * event, terminated by the host's synthetic `{"type":"end"}` marker.
 *
 * The plugin author never specifies a destination — the host bridge derives
 * it from the iframe's identity. Run invocations sequentially (`await` each
 * stream to completion before starting the next); concurrent invocations from
 * the same iframe produce interleaved streams this transport cannot demux
 * (there is no per-invocation tag on `cli_command` events).
 *
 * Requires the objectiveai cli to be installed on the host
 * (`~/.objectiveai/objectiveai`). When the spawn fails the host streams back
 * a `{"type":"error",…}` envelope followed by `{"type":"end"}`, so the stream
 * still terminates. Outside an iframe (standalone dev) it warns and yields
 * nothing.
 */
declare class ViewerCommandExecutor {
    execute(request: CliCommandRequest): AsyncIterable<unknown>;
}

/**
 * Any of the three CLI command executors. The generated per-command execute
 * functions accept one of these and call `.execute(request)` on it.
 */
type CommandExecutor = BinaryCommandExecutor | PluginCommandExecutor | ViewerCommandExecutor;

